const g = (k, l) => String($json[k] ?? $json[l] ?? '').trim();
const req = { lead_id: g('lead_id', 'Lead ID').toUpperCase(), unit_id: g('unit_id', 'Unit ID').toUpperCase(), date: g('date', 'Date').slice(0, 10), time: g('time', 'Time'), advisor_email: g('advisor_email', 'Advisor email') };
const start = DateTime.fromFormat(req.date + ' ' + req.time, 'yyyy-MM-dd HH:mm', { zone: 'Africa/Cairo' });
const problems = [];
if (!/^L-\d{6}-[A-Z0-9]{4}$/.test(req.lead_id)) problems.push('Lead ID format is L-YYMMDD-XXXX');
if (!/^U-\d+$/.test(req.unit_id)) problems.push('Unit ID format is U-101');
if (!start.isValid) problems.push('date or time is invalid');
else { if (start < $now.setZone('Africa/Cairo').plus({ hours: 2 })) problems.push('viewings need at least 2 hours notice');
  if (start.weekday === 5) problems.push('no viewings on Friday'); }
return [{ json: { ...req, start: start.isValid ? start.toISO() : '', end: start.isValid ? start.plus({ hours: 1 }).toISO() : '', problems, ok: problems.length === 0 } }];

const req = $('Validate Viewing Request').first().json; const lead = $('Find Lead').first().json; const unit = $input.first().json;
const problems = [];
if (!lead.lead_id) problems.push('lead ' + req.lead_id + ' not found');
if (!unit.unit_id) problems.push('unit ' + req.unit_id + ' not found'); else if (unit.status !== 'available') problems.push('unit ' + req.unit_id + ' is ' + unit.status);
return [{ json: { ...req, lead, unit, problems, ok: problems.length === 0 } }];
